content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #1a1a2e;
  color: #e6e6e6;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.piano-container {
  background: #16213e;
  border-radius: 16px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  padding: 30px;
  max-width: 700px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  border: 1px solid #0f3460;
}

.header {
  text-align: center;
  margin-bottom: 25px;
}

.header h1 {
  font-size: 2rem;
  margin-bottom: 8px;
  color: #e94560;
  letter-spacing: 1px;
}

.info-text {
  font-size: 0.95rem;
  color: #a0a0a5;
  line-height: 1.4;
}

.keyboard-wrapper {
  width: 100%;
  overflow-x: auto;
  padding-bottom: 10px;
  display: flex;
  justify-content: center;
}

.keyboard {
  position: relative;
  display: flex;
  height: 220px;
  background-color: #0f3460;
  padding: 10px;
  border-radius: 8px;
  box-shadow: inset 0 2px 5px rgba(0,0,0,0.3);
}

.white-key {
  position: relative;
  width: 48px;
  height: 200px;
  background: #ffffff;
  border: 1px solid #cccccc;
  border-radius: 0 0 6px 6px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 15px;
  transition: background-color 0.1s, box-shadow 0.1s;
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
  z-index: 1;
  user-select: none;
}

.white-key:hover {
  background: #f0f0f0;
}

.white-key.active {
  background: #d4d4d8;
  box-shadow: inset 0 4px 6px rgba(0,0,0,0.2);
  transform: translateY(2px);
}

.black-key {
  position: absolute;
  width: 30px;
  height: 120px;
  background: #1f1f1f;
  border-radius: 0 0 4px 4px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 10px;
  transition: background-color 0.1s, box-shadow 0.1s;
  box-shadow: 0 4px 6px rgba(0,0,0,0.3);
  z-index: 2;
  user-select: none;
}

.black-key:hover {
  background: #333333;
}

.black-key.active {
  background: #000000;
  box-shadow: inset 0 3px 5px rgba(255,255,255,0.2);
  transform: translateY(2px);
}

.key-label {
  font-size: 0.75rem;
  font-weight: bold;
  pointer-events: none;
}

.white-key .key-label {
  color: #555555;
}

.black-key .key-label {
  color: #cccccc;
}

.controls {
  margin-top: 25px;
  display: flex;
  gap: 15px;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  background-color: #e94560;
  color: white;
  border: none;
  padding: 10px 20px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  box-shadow: 0 4px 10px rgba(233, 69, 96, 0.3);
}

.btn:hover {
  background-color: #ff6b81;
}

.btn:active {
  transform: scale(0.97);
}

.btn:disabled {
  background-color: #4a4a5a;
  cursor: not-allowed;
  box-shadow: none;
}

export interface NoteKey {
  note: string;
  freq: number;
  isBlack: boolean;
  label: string;
  keyName: string;
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { NoteKey } from './types';

const KEYS: NoteKey[] = [
  { note: 'C4', freq: 261.63, isBlack: false, label: 'C', keyName: 'KeyZ' },
  { note: 'C#4', freq: 277.18, isBlack: true, label: 'C#', keyName: 'KeyS' },
  { note: 'D4', freq: 293.66, isBlack: false, label: 'D', keyName: 'KeyX' },
  { note: 'D#4', freq: 311.13, isBlack: true, label: 'D#', keyName: 'KeyD' },
  { note: 'E4', freq: 329.63, isBlack: false, label: 'E', keyName: 'KeyC' },
  { note: 'F4', freq: 349.23, isBlack: false, label: 'F', keyName: 'KeyV' },
  { note: 'F#4', freq: 369.99, isBlack: true, label: 'F#', keyName: 'KeyG' },
  { note: 'G4', freq: 392.00, isBlack: false, label: 'G', keyName: 'KeyB' },
  { note: 'G#4', freq: 415.30, isBlack: true, label: 'G#', keyName: 'KeyH' },
  { note: 'A4', freq: 440.00, isBlack: false, label: 'A', keyName: 'KeyN' },
  { note: 'A#4', freq: 466.16, isBlack: true, label: 'A#', keyName: 'KeyJ' },
  { note: 'B4', freq: 493.88, isBlack: false, label: 'B', keyName: 'KeyM' },
  { note: 'C5', freq: 523.25, isBlack: false, label: 'C5', keyName: 'KeyComma' },
];

const SONG_SAMPLE = [
  { note: 'C4', duration: 400 },
  { note: 'C4', duration: 400 },
  { note: 'G4', duration: 400 },
  { note: 'G4', duration: 400 },
  { note: 'A4', duration: 400 },
  { note: 'A4', duration: 400 },
  { note: 'G4', duration: 800 },
  { note: 'F4', duration: 400 },
  { note: 'F4', duration: 400 },
  { note: 'E4', duration: 400 },
  { note: 'E4', duration: 400 },
  { note: 'D4', duration: 400 },
  { note: 'D4', duration: 400 },
  { note: 'C4', duration: 800 },
];

export default function App() {
  const [activeNotes, setActiveNotes] = useState<Record<string, boolean>>({});
  const [isPlayingSong, setIsPlayingSong] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      audioCtxRef.current = new AudioContextClass();
    }
    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  };

  const playTone = useCallback((freq: number, note: string) => {
    try {
      const ctx = getAudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, ctx.currentTime);

      gain.gain.setValueAtTime(0.3, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.8);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start();
      osc.stop(ctx.currentTime + 0.8);

      setActiveNotes((prev) => ({ ...prev, [note]: true }));
      setTimeout(() => {
        setActiveNotes((prev) => ({ ...prev, [note]: false }));
      }, 200);
    } catch {
      // AudioContext error handling
    }
  }, []);

  const handleNoteClick = (noteKey: NoteKey) => {
    playTone(noteKey.freq, noteKey.note);
  };

  const playSampleSong = () => {
    if (isPlayingSong) return;
    setIsPlayingSong(true);

    let delay = 0;
    SONG_SAMPLE.forEach((item, index) => {
      setTimeout(() => {
        const found = KEYS.find((k) => k.note === item.note);
        if (found) {
          playTone(found.freq, found.note);
        }
        if (index === SONG_SAMPLE.length - 1) {
          setTimeout(() => setIsPlayingSong(false), 500);
        }
      }, delay);
      delay += item.duration;
    });
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return;
      const found = KEYS.find((k) => k.keyName === e.code);
      if (found) {
        playTone(found.freq, found.note);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [playTone]);

  // 黒鍵のオフセット計算用（白鍵の並びに対する位置調整）
  // 白鍵のインデックスに基づいて左からの位置を決定
  const whiteKeys = KEYS.filter((k) => !k.isBlack);

  const getBlackKeyLeft = (note: string) => {
    switch (note) {
      case 'C#4': return '36px';
      case 'D#4': return '84px';
      case 'F#4': return '180px';
      case 'G#4': return '228px';
      case 'A#4': return '276px';
      default: return '0px';
    }
  };

  return (
    <div className="piano-container">
      <header className="header">
        <h1>インタラクティブピアノ</h1>
        <p className="info-text">
          1オクターブの鍵盤をクリックまたはキーボード（Z〜, / S,D,G,H,J）で演奏できます。<br />
          自動演奏ボタンでサンプル曲をお楽しみください。
        </p>
      </header>

      <div className="keyboard-wrapper">
        <div className="keyboard">
          {whiteKeys.map((k) => (
            <div
              key={k.note}
              className={`white-key ${activeNotes[k.note] ? 'active' : ''}`}
              onMouseDown={() => handleNoteClick(k)}
              onTouchStart={(e) => {
                e.preventDefault();
                handleNoteClick(k);
              }}
            >
              <span className="key-label">{k.label}</span>
            </div>
          ))}

          {KEYS.filter((k) => k.isBlack).map((k) => (
            <div
              key={k.note}
              className={`black-key ${activeNotes[k.note] ? 'active' : ''}`}
              style={{ left: getBlackKeyLeft(k.note) }}
              onMouseDown={(e) => {
                e.stopPropagation();
                handleNoteClick(k);
              }}
              onTouchStart={(e) => {
                e.stopPropagation();
                e.preventDefault();
                handleNoteClick(k);
              }}
            >
              <span className="key-label">{k.label}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="controls">
        <button
          className="btn"
          onClick={playSampleSong}
          disabled={isPlayingSong}
        >
          {isPlayingSong ? '演奏中...' : 'サンプル曲を自動演奏'}
        </button>
      </div>
    </div>
  );
}
